---@class SDKService
---@field GetInstance fun(self:SDKService):SDKService
local SDKService = Class("SDKService", Singleton)
---@field thirdSDK BaseSdkUtils[]
function SDKService:__init()
    ---注册登录sdk的相关回调
    self._handler = Bind(self, self.__SDKHandler)
    self.isLogin = false
    self.loginIng = false -- 是否正在登录过程中
    SDKCenter.SetDelegateCallback(self._handler)

    -- self._winYiDunTimeDown = nil 
    -- self._curYiDunLoopTime = 0

    self._PayMoneyTable = {}
    self._region = nil
    self.thirdSDK = {}
    -- 发送ace data 数据
    self:AceSDKCall("AceDataSend")
end

function SDKService:__delete()
    self._handler = nil
    SDKCenter.SetDelegateCallback(nil)
    -- self._winYiDunTimeDown = nil
    -- self._curYiDunLoopTime = nil
    self._PayMoneyTable = nil
    self._region = nil
    for k, v in pairs(self.thirdSDK) do
        v:Delete()
    end
    self.thirdSDK = nil

end

---__SDKHandler
--- sdk回调事件的逻辑处理
---@param errorCode number
---@param extras string
function SDKService:__SDKHandler(errorCode, extras)
    logs(string.format('<color=#996633>[SDK handler] %s : </color>', tostring(errorCode)), extras or '')
    if errorCode == Constants.SdkErrorCode.LoginSuccess then
        x_record_event(RecordEvents.ACCOUNT_SUCCESS)
        local t = table.deserialize(extras)
        ---@type ECSWorldMgr
        local worldMgr = ECSWorldMgr:GetInstance()
        ---@type ECSWorld
        local world = worldMgr:GetWorld(Constants.GameWorld)
        ---@type ECSEntity
        local entity = world:GetEntity(Constants.PlayerEntityId)
        ---先移除一次防止记录了上一次账号的serverId然后不会走创角的问题
        entity:RemoveComp(ECSComponentType.Constants.UserComponent)
        ---@type UserComponent
        local userComp = entity:GetOrAddComp(ECSComponentType.Constants.UserComponent)
        userComp:UpdateSDKInfo(t)
        local channelData = { openId = t.openId, loginTimestamp = t.timestamp, loginSign = t.sign }
        if isNotNull(t.subOpenId)  then
            channelData.subOpenId = t.subOpenId
        end
        -- 判断身份证信息是否合法
        if t.idNo and string.len(tostring(t.idNo)) > 5 then
            -- 合法传输t.idNo
            channelData.idNumber = t.idNo
        end
        -- channelLogin 前登陆前， 清除 SessionId  ， PlayerId ，UserId
        local HttpModule = CS.Engine.Http.HttpModule
        HttpModule.RequestBodyMeta.SessionId = ""
        HttpModule.RequestBodyMeta.PlayerId = ""
        HttpModule.RequestBodyMeta.UserId = ""
        self.loginIng = true
        if self.IsQuick and self:IsQuick() then
            HttpModule.RequestBodyMeta.SubChannelId = CS.Engine.Lib.AndroidPlugin.getQudaoChannelId()
        end
        ---登录的逻辑
        GameUtils.Request(Interfaces.ChannelLogin, channelData,
                function(request, response)
                    if checkNumber(response.errCode) == 0 then
                        self:SetIsLogin(true)
                        local data = checkTable(response.data)
                        data.country_code = t.country_code
                        userComp:Initial(data)
                        if checkInt(data.isQueueOpened) == 1 and tonumber(data.queueNum) ~= 0 then
                            userComp:GoToQueueDialog(data.queueNum, function()
                                Events.Broadcast(Constants.EventNames.EVENT_SDK, { event = Constants.EventNames.EVENT_SDK_LOGIN, data = data })
                            end)
                        else
                            Events.Broadcast(Constants.EventNames.EVENT_SDK, { event = Constants.EventNames.EVENT_SDK_LOGIN, data = data })
                        end
                        self.loginIng = false
                        local servers = userComp.userInfo.servers
                        local KCookie = CS.Engine.Lib.KCookie
                        KCookie.Set('Ace_Close', checkInt(userComp.userInfo.aceDataReport))
                        if checkInt(userComp.userInfo.lastLoginServerId) > 0 then
                            HttpModule.RequestBodyMeta.serverId = tostring(userComp.userInfo.lastLoginServerId)
                            ---@type UserComponent
                            local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
                            if isNotNull(userComponent) then
                                userComponent:SetRequestBodyMetaServerAreaId()
                            end
                        end
                        local serverDojo = userComp:GetServerById(userComp.userInfo.lastLoginServerId)
                        local sumPayCumulative = 0
                        if userComp.userInfo.servers and #userComp.userInfo.servers > 0 then
                            for k, v in pairs(userComp.userInfo.servers) do
                                sumPayCumulative = checkInt(v.payCumulative) + sumPayCumulative
                            end
                            userComp:SetSumPayCumulative(sumPayCumulative)
                        end
                        --  设置玩家角色
                        if servers and #servers > 0 then
                            -- 此处如果没有roleId 不上传角色信息
                            if serverDojo then
                                if checkInt(serverDojo.playerId) > 0 and checkInt(serverDojo.playerLevel) > 0 then
                                    local roles = {
                                        serverId = serverDojo.serverId,
                                        serverName = serverDojo.serverName,
                                        roleId = serverDojo.playerId,
                                        roleName = serverDojo.playerName,
                                        roleLevel = serverDojo.playerLevel,
                                        pay_point = tostring(userComp:GetSumPayCumulative()),
                                        channelId = tostring(GameUtils.GetChannelId()),
                                        RechargePts = tostring(sumPayCumulative)
                                        -- gameJson = self:GetGameJsonStr()
                                    }
                                    -- 用于用户中心使用 ， 玩家id ， 玩家昵称  ， 服务器id ， 服务器名称
                                    self:SetGameRole(roles)
                                    local content = clone(roles)
                                    content.customData = table.serialize({
                                        AccountID = tostring(userComp.userInfo.openId),
                                        RechargePts = tostring(sumPayCumulative)
                                    })
                                    self:updateElexUserInfo(content)
                                end
                            end
                        else

                            local content = {
                                customData = table.serialize({
                                    AccountID = userComp.userInfo.openId,
                                    RechargePts = tostring(sumPayCumulative)
                                })
                            }
                            self:updateElexUserInfo(content)
                        end
                        --登陆完成PC端通知开启ACE
                        if serverDojo then
                            if GameUtils.IsWindow() then
                                Events.Broadcast(Constants.EventNames.WinSDK, { type = 12, serverId = serverDojo.serverId })
                            end
                        end
                    else
                        self.loginIng = false
                    end
                    self:getAdjustIds()
                    self:UpdateThZoneByEnLang()
                end, function(exception)
                    self.loginIng = false
                    GameUtils.Toast(exception.Message)
                end)
    elseif errorCode == Constants.SdkErrorCode.LoginCancel or errorCode == Constants.SdkErrorCode.LoginFail then
        self.loginIng = false
    elseif errorCode == Constants.SdkErrorCode.PayDMM_CALL_BACK_WEB then
        local t = table.deserialize(extras)
        -- {itemId = xx, name=xxx, price = xxx, quantity = xxx, callbackUrl = xxx, finishUrl = xxx}
        CS.Engine.Lib.MyLogger.LogToFile("==>>" .. table.dump(t, false, 2))
        local data = {
            itemId = (string.isEmpty(t.product_id) and t.channel_product_id or t.product_id ),
            name = tostring(t.product_subject),
            price = math.floor(checkNumber(t.amount) / 100),
            quantity = 1,
            callbackUrl = tostring(t.success_url),
            finishUrl = tostring(t.finish_url)
        }
        CS.Engine.Lib.MyLogger.LogToFile("==>>" .. table.dump(data, false, 2) .. "\n")
        self:DMMExecute(2, function(kind, ret)
            CS.Engine.Lib.MyLogger.LogToFile("==>>" .. tostring(ret))
            Events.Broadcast(Constants.EventNames.WinSDK, { type = 996, reqData = {payment_id = checkString(ret.payment_id)} })
        end, data)
    elseif errorCode == Constants.SdkErrorCode.PaySuccess
            or errorCode == Constants.SdkErrorCode.PayCancel
            or errorCode == Constants.SdkErrorCode.PayFail
            or errorCode == Constants.SdkErrorCode.PayRestore
            or errorCode == Constants.SdkErrorCode.PayProgress then
        local t = table.deserialize(extras)
        self:PayResult(t, errorCode)
    elseif errorCode == Constants.SdkErrorCode.EnterGame then
        print("IsEnterSuccess =>", checkNumber(CS.Engine.Lib.KCookie.Get("IsEnterSuccess")))
        if checkNumber(CS.Engine.Lib.KCookie.Get("IsEnterSuccess")) == 1 then
            return
        end
        CS.Engine.Lib.KCookie.Set("IsEnterSuccess", 1)
        --进入游戏接口成功
        local t = {}
        if extras then
            t = table.deserialize(extras)
        end
        Events.Broadcast(Constants.EventNames.EVENT_SDK, { event = Constants.EventNames.EVENT_SDK_ENTER_GAME, data = t })
    elseif errorCode == Constants.SdkErrorCode.KickOut then
        ---用户注销与未成年情况处理
        local t = {}
        if extras then
            t = table.deserialize(extras)
        end
        local text = ''
        if checkString(t.state) == 'logout' then
            text = localize("当前用户已退出登录")
        elseif checkString(t.state) == 'minor' then
            ---未成年
            text = localize("未成年已限时")
        elseif checkString(t.state) == 'login_invalid' then
            text = localize("登陆状态已失效，请重新登陆")
        end

        local quitFun = function()
            if GameUtils.IsWindow() then
                CS.System.Diagnostics.Process.GetCurrentProcess():Kill()
            else
                local I18NModule = CS.Engine.I18N.I18NModule
                local lange = I18NModule.Lang
                -- 国服sdk android 单独处理
                if self:IsCN() and kTool.UNITY_ANDROID() then
                    self:Logout()
                else
                    self:LogoutGame()
                end
                --  CS.UnityEngine.Application.Quit()
            end
        end
        ---session过期
        GameUtils.SecondConfirm(text, function()
            ---退到登录页面
            --CS.UnityEngine.Application.Quit()
            quitFun()
            ---退到登录页面的逻辑暂缓
        end, function()
            --CS.UnityEngine.Application.Quit()
            quitFun()
        end)
    elseif errorCode == Constants.SdkErrorCode.LogoutFinish then
        self:LogoutGame()
    elseif errorCode == Constants.SdkErrorCode.RefreshAccount then
        local t = table.deserialize(extras)
        -- 刷新账号信息忽略调 sign 和 timestamp
        t.sign = nil
        t.timestamp = nil
        ---@type ECSWorldMgr
        local worldMgr = ECSWorldMgr:GetInstance()
        ---@type ECSWorld
        local world = worldMgr:GetWorld(Constants.GameWorld)
        ---@type ECSEntity
        local entity = world:GetEntity(Constants.PlayerEntityId)
        ---@type UserComponent
        local userComp = entity:GetOrAddComp(ECSComponentType.Constants.UserComponent)
        -- 检测isUnResetUserId 是否存在，不存在直接return
        if isNull(userComp) then
            return
        end
        userComp:UpdateSDKInfo(t, true)
    elseif errorCode == Constants.SdkErrorCode.BindAccount then
        if kTool.UNITY_IOS() then
            ---@type ECSWorldMgr
            local worldMgr = ECSWorldMgr:GetInstance()
            ---@type ECSWorld
            local world = worldMgr:GetWorld(Constants.GameWorld)
            ---@type ECSEntity
            local entity = world:GetEntity(Constants.PlayerEntityId)
            ---@type UserComponent
            local userComp = entity:GetOrAddComp(ECSComponentType.Constants.UserComponent)
            -- 检测isUnResetUserId 是否存在，不存在直接return
            if isNull(userComp) then
                return
            end
            userComp:UpdateSDKInfo({ is_guest = 0 }, true)
        end

    elseif errorCode == Constants.SdkErrorCode.QueryPrice or errorCode == Constants.SdkErrorCode.PayProdustList then
        self:PayUtilsCall("QueryPricesCallBack", extras)
    elseif errorCode == Constants.SdkErrorCode.ShareSuccess then
        self:ShareSuccess()
    elseif errorCode == Constants.SdkErrorCode.ShareFail then
        GameUtils.Toast(localize("分享失败"))
        return
    elseif errorCode == Constants.SdkErrorCode.QueryYidunResult then
        local t = table.deserialize(extras)
        self:YiDunCallBack(t)
    elseif errorCode == Constants.SdkErrorCode.CommunityClose then
        self:CloseCommunityEvent()
    elseif errorCode == Constants.SdkErrorCode.HealthTip then
        local t = table.deserialize(extras)
        local messageTickerUtils = import("Game.UI.MessageTicker.MessageTickerUtils")
        messageTickerUtils.ShowMessageById(1, { _time_ = t.hour }, 0)
    elseif errorCode == Constants.SdkErrorCode.FireBaseTokenResult then
        local t = table.deserialize(extras)
        if isNotNull(t.token) and string.len(t.token) > 0 then
            self:FirebaseRefreshToken(t)
        elseif t.isOpenNotice then
            if checkInt(t.isOpenNotice) == 1 then
                local PlayerPrefsUtility = CS.Engine.Tools.PlayerPrefsUtility
                PlayerPrefsUtility.SetEncryptedString("isOpenNotice", "1")
                PlayerPrefsUtility.Save()
            else
                local PlayerPrefsUtility = CS.Engine.Tools.PlayerPrefsUtility
                PlayerPrefsUtility.SetEncryptedString("isOpenNotice", "0")
                PlayerPrefsUtility.Save()
            end
        end
    elseif errorCode == Constants.SdkErrorCode.AIHelperNewMessage then
        -- 有新消息的通知
        local t = table.deserialize(extras)
        local PlayerPrefsUtility = CS.Engine.Tools.PlayerPrefsUtility
        if checkInt(t.isNew) > 0 then
            PlayerPrefsUtility.SetEncryptedString("AIHelperNewMessage", "1")
        else
            PlayerPrefsUtility.SetEncryptedString("AIHelperNewMessage", "0")
        end
        PlayerPrefsUtility.Save()
        local dialog = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.UIHomeView)
        if isNotNull(dialog) then
            if checkInt(t.isNew) > 0 then
                GameUtils.SetRedPointNum(Constants.RedPointConst.ConnectSever, 1)
            else
                GameUtils.SetRedPointNum(Constants.RedPointConst.ConnectSever, 0)
            end
            GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.ConnectSever)
        end
    elseif errorCode == Constants.SdkErrorCode.AdjustIdsResult then
        if string.len(extras) == 0 then
            return
        end
        if not kTool.IsMobile() then
            return
        end
        local t = table.deserialize(extras)
        local httpModule = CS.Engine.Http.HttpModule
        if string.len(t.adjustId) > 0 then
            PlayerPrefsUtility.SetEncryptedString("adjustId", t.adjustId)
            PlayerPrefsUtility.Save()
        end
        if kTool.UNITY_ANDROID() then
            local PlayerPrefsUtility = CS.Engine.Tools.PlayerPrefsUtility
            httpModule.RequestBodyMeta.IdFa = t.gpsAdid
        else
            httpModule.RequestBodyMeta.IdFa = t.idfa
        end
        self:PayAdjust()
    elseif errorCode == Constants.SdkErrorCode.AppFlyerIdResult then
        local t = table.deserialize(extras)
        self:PayAppFlyerId(t.appFlyerId)
    elseif errorCode == Constants.SdkErrorCode.PayAdditionalParams then
        local t = table.deserialize(extras)
        self:PayMoney(t)
    elseif errorCode == Constants.SdkErrorCode.FillCodeBindAccount then
        -- 1.如果在游戏内存引继， 直接调用退出游戏 
        -- 2.如果是在主界面引继，直接调用重新登录 
        local dialog = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.LoginDialog)
        if isNull(dialog) then
            self:Logout()
        else
            self:Login()
        end
    end
end
-- 国服渠道分包
function SDKService:IsCnSubpackage()
    local channelId = GameUtils.GetChannelId()
    if channelId >= 5100 and channelId <= 5200  then
        return true
    end
    return false
end
function SDKService:IsCN()
    if self:IsCnSubpackage() then
        return true
    end
    local channelId = GameUtils.GetChannelId()
    if channelId >= 5043 and channelId <= 5047 then
        return true
    end
    return false
end
