--- func desc 当是英语时 泰国的ios 设备显示泰语异常，所以 泰国ios 统一用ios 字体
function SDKService:UpdateThZoneByEnLang()
    if self:IsSea() and kTool.UNITY_IOS() then
        local staticType = CS.Engine.Lib.UII18nText    
        xlua.private_accessible(CS.Engine.Lib.UII18nText)
        local s_TextConfig =  CS.Engine.Lib.UII18nText.s_TextConfig
        if s_TextConfig then
            local font = nil
            local heavyFont = nil
            local language = nil
            for i = 0 , s_TextConfig.fontEntries.Length -1 do
                local v = s_TextConfig.fontEntries[i]
                if v.language == "th_TH" then
                    language = v.language
                    font = v.font
                    heavyFont = v.heavyFont
                    break
                end
            end
            if isNotNull(font) and isNotNull(heavyFont) then
                for i = 0 , s_TextConfig.fontEntries.Length -1 do
                    local v = s_TextConfig.fontEntries[i]
                    if v.language == "en_UK" then
                        v.font = font
                        v.heavyFont = heavyFont
                    end
                end
            end
        end    
    end
end
