function SDKService:FirebaseRefreshToken(data)
    local httpModule = CS.Engine.Http.HttpModule
    local playerId = httpModule.RequestBodyMeta.PlayerId
    if checkInt(playerId) > 0 then
        GameUtils.Request(Interfaces.FirebaseRefreshToken, { token = data.token }, function(request, response)

        end,
                function(exception)
                    self.loginIng = false
                    GameUtils.Toast(exception.Message)
                end, nil, nil, false
        )
    end
end

function SDKService:PayAdjust()
    if not (self:IsZm() and kTool.IsMobile()) then
        return
    end
    local adjustId = PlayerPrefsUtility.GetEncryptedString("adjustId", "")
    if string.len(adjustId) > 0 then
        local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        if playerComp and playerComp.playerDojo and checkNumber(playerComp.playerDojo.playerId) > 0 then
            GameUtils.Request(Interfaces.PayAdjust, { adjustId = adjustId }, function(request, response)

            end,
                    function(exception)
                        self.loginIng = false
                        GameUtils.Toast(exception.Message)
                    end, nil, nil, false
            )
        end
    end
end

function SDKService:PayAppFlyerId(appFlyerId)
    if not (self:IsJP() and self:IsForeignSDK()) then
        return
    end
    if isNotNull(appFlyerId) and (not string.isEmpty(appFlyerId)) then
        local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        if playerComp and playerComp.playerDojo and checkNumber(playerComp.playerDojo.playerId) > 0 then
            if string.isEmpty(CS.Engine.Http.HttpModule.RequestBodyMeta.PlayerId) then
                CS.Engine.Http.HttpModule.RequestBodyMeta.PlayerId = playerComp.playerDojo.playerId
            end
            GameUtils.Request(Interfaces.PayAppsflyer, { appsFlyerId = appFlyerId }, function(request, response)

            end,
                    function(exception)
                        self.loginIng = false
                        GameUtils.Toast(exception.Message)
                    end, nil, nil, false
            )
        end
    end
end

function SDKService:CloseCommunityEvent()
    if kTool.UNITY_IOS() then
        ---@type CriWareUtils
        local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
        local customSoundSettingsData = PlayerPrefsUtility.GetEncryptedString("customSoundSettings")
        if string.isEmpty(customSoundSettingsData) then
            CriWareUtils.ResetVolume(Constants.CriWareCategory.BGM)
        else
            local data = table.deserialize(customSoundSettingsData)
            CriWareUtils.SetVolume(Constants.CriWareCategory.BGM, data.Music.Slider)
        end
    end
end
