function SDKService:PayResult(t, code)
    --elseif errorCode == Constants.SdkErrorCode.PaySuccess
    --or errorCode == Constants.SdkErrorCode.PayCancel
    --or errorCode == Constants.SdkErrorCode.PayFail
    --or errorCode == Constants.SdkErrorCode.PayProgress then

    if code == Constants.SdkErrorCode.PayCancel then
        self:CloseNetWorkDialog()
        GameUtils.Toast(localize("支付取消"))
        return
    end
    if code == Constants.SdkErrorCode.PayFail then
        self:CloseNetWorkDialog()
        GameUtils.Toast(localize("支付失败"))
        return
    end

    if code == Constants.SdkErrorCode.PayProgress then
        GameUtils.Toast(localize("支付过程中"))
        return
    end
    if code == Constants.SdkErrorCode.PayRestore then
        self:CloseNetWorkDialog()
        GameUtils.Toast(localize("恢复购买成功"))
        return
    end
    if code == Constants.SdkErrorCode.FinishPaymentTransaction then
        return
    end
    -- 成功之前 必须关闭界面
    if code == Constants.SdkErrorCode.PaySuccess then
        if self:IsCommonSDK() then
            local orderNo = t.orderId
            local productId = t.productId
            ---@type PlayerComponent
            local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            if isNull(playerComponent) then
                return
            end
            if isNull(playerComponent:GetPlayerDojo()) then
                return
            end
            if checkInt(playerComponent:GetPlayerDojo().playerId) <= 0 then
                return
            end
            ---支付成功
            GameUtils.Request(Interfaces.PayInfo .. '/' .. os.time(), { orderNo = orderNo },
                    function(request, response)
                        self:CloseNetWorkDialog()
                        if checkNumber(response.errCode) == 0 then
                            local data = checkTable(response.data)
                            ---@type PlayerComponent
                            local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)

                            if isSet(data, "diamond") then
                                playerComp.playerDojo.diamond = checkNumber(data.diamond)
                                ---弹出一个表现的ui奖励
                                ----统一放在rewards里面弹出来
                                --CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = {
                                --    { goodsId = Constants.Currency.PayDiamondId, num = checkNumber(data.diamondNum) }
                                --} } })
                                Events.Broadcast(Constants.EventNames.EveryThingChangeEventName, checkNumber(Constants.Currency.PayDiamondId))
                            end
                            if isSet(data, "payPoint") then
                                local amountEx = playerComp.playerDojo.payCumulative
                                playerComp.playerDojo.payCumulative = checkNumber(amountEx) + checkNumber(data.payPoint)
                            end
                            if isSet(data, "showVip") then
                                xTry(function()
                                    playerComp.playerDojo.showVip = checkNumber(data.showVip)
                                    --GameUtils.SetRedPointNum(Constants.RedPointConst.VipFund, checkNumber(data.showVip))
                                    --GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.VipFund)
                                end)
                            end
                            ---策划说充钱错不会再带有奖励
                            if isSet(data, "rewards") then
                                if table.count(checkTable(data.rewards)) > 0 then
                                    GoodsUtils.DrawRewards(checkTable(data.rewards), true)
                                    CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = clone(data.rewards) } })
                                end
                            end
                            if isSet(data, "monthCard") then
                                local storeUtils = import('Game.UI.Store.StoreUtils')
                                local comp = storeUtils.GetStoreComp()
                                comp:RefreshMonthCardInfo(data.monthCard)
                            end
                            Events.Broadcast(Constants.EventNames.EVENT_SDK, { event = Constants.EventNames.EVENT_SDK_PAY, data = data, productId = productId })
                            self:TrackReYunEvent("purchase", {
                                contentID = tostring(orderNo),
                                payChannel = tostring(GameUtils.GetChannelId()),
                                currency = "CNY",
                                actuallyAmount = checkInt(checkInt(t.amount) / 100),
                            })
                            if isSet(data, "windowsPriceId") then
                                local price = self:PayUtilsCall("GetUSDPriceByWindowsPriceId", data.windowsPriceId)
                                if IS_REVIEW_INT <= 0 then
                                    if checkNumber(price) > 0 then
                                        if isSet(data, "firstPay") then
                                            playerComp.playerDojo.firstPay = checkInt(data.firstPay)
                                            if not self:IsJP() then
                                                xRecord.af_internal("firstpay", { playerId = tostring(playerComp.playerDojo.playerId), af_revenue = tostring(price), af_currency = "USD" })
                                                xRecord.af_internal(string.format("af_recharge_%s", tostring(price)), { playerId = tostring(playerComp.playerDojo.playerId), productId = productId })
                                            end
                                            if xRecord.adjust_internal then
                                                xRecord.adjust_internal({ event = "recharge", af_revenue = tostring(price), af_currency = "USD", productId = productId, orderId = orderNo })
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end, function(exception)
                        self:CloseNetWorkDialog()
                        GameUtils.Toast(exception.Message)
                    end)
        else
            self:CloseNetWorkDialog()
        end
    else
        self:CloseNetWorkDialog()
    end
end

