local DMM_CHANNEL_ID = 6006

---Login
---开始登录
function SDKService:Login(isSwitch)
    if self.loginIng then
        return
    end
    if self:IsCommonSDK() then
        x_record_event(RecordEvents.ACCOUNT_START)
        if GameUtils.IsWindow() then
            --[[
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIWindowLoginDialog, parameters = { sdkType = 1, cb = function(errorCode, extras, controller)
                self:__SDKHandler(errorCode, extras, function()
                    --UIModule.CloseDialog(controller)
                end)
                UIModule.CloseDialog(controller)
            end } })
            ]]
            if isSwitch then
                Events.Broadcast(Constants.EventNames.WinSDK, { type = 7 })
            else
                if GameUtils.GetChannelId() == DMM_CHANNEL_ID then
                    self:DMMExecute(1, function(kind)
                        Events.Broadcast(Constants.EventNames.WinSDK, { type = 998 })
                    end)
                else
                    Events.Broadcast(Constants.EventNames.WinSDK, { type = 2 })
                end
            end
        else
            SDKCenter.Login()
        end
    else
        x_record_event(RecordEvents.ACCOUNT_START)
        if Config.WriteAccount then
            local storeValue = PlayerPrefsUtility.GetEncryptedString(Config.LastLoginUserPasswordPreferenceKey)
            if not string.isEmpty(storeValue) then
                local t = table.deserialize(storeValue)
                ---记录了上次登录的账户密码
                GameUtils.Request(Interfaces.UserLogin, { uname = t.username, password = t.password },
                        function(request, response)
                            if checkNumber(response.errCode) == 0 then
                                self:SetIsLogin(true)
                                x_record_event(RecordEvents.ACCOUNT_SUCCESS)
                                local data = checkTable(response.data)
                                ---@type ECSWorldMgr
                                local worldMgr = ECSWorldMgr:GetInstance()
                                ---@type ECSWorld
                                local world = worldMgr:GetWorld(Constants.GameWorld)
                                ---@type ECSEntity
                                local entity = world:GetEntity(Constants.PlayerEntityId)
                                ---@type UserComponent
                                local userComp = entity:GetOrAddComp(ECSComponentType.Constants.UserComponent)
                                userComp:Initial(data)
                                local lastLoginServerId = checkInt(userComp.userInfo.lastLoginServerId)
                                if lastLoginServerId > 0 then
                                    local HttpModule = CS.Engine.Http.HttpModule
                                    HttpModule.RequestBodyMeta.serverId = tostring(lastLoginServerId)
                                    ---@type UserComponent
                                    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
                                    if isNotNull(userComponent) then
                                        userComponent:SetRequestBodyMetaServerAreaId()
                                    end
                                end
                                Events.Broadcast(Constants.EventNames.EVENT_SDK, { event = Constants.EventNames.EVENT_SDK_LOGIN, data = data })
                            end
                        end, function(exception)
                            GameUtils.Toast(exception.Message)
                        end)
            else
                Events.Broadcast(Constants.EventNames.EVENT_SDK, { event = Constants.EventNames.EVENT_SDK_LOGIN })
            end
        end
    end
end

