            GameUtils.SecondConfirm(localize("是否消费_num_积分购买_name_", {_num_ = checkNumber(parameters.payAmount), _name_ = parameters.productDesc}), function()
                self:PayMoney(parameters, true)
            end, function()

            end, localize("DMM积分消费数量: _num_ _NEW_LINE_DMM积分拥有数量: _amount_", {_num_ = checkNumber(parameters.payAmount), _amount_ = userComp.userInfo.canUsePoint}))
        else
