---PayMoney
---调用支付的方法：
---     官方服是参数必有：{productId, productDesc, payAmount, channelProductId}
---@param parameters table
---@param isSkip boolean
function SDKService:PayMoney(parameters, isSkip)
    isSkip = checkBool(isSkip)
    --if GameUtils.IsWindow() or kTool.UNITY_STANDALONE() or CS.Engine.Lib.AppEngine.GetAppBundleVersion().Server == 'pre'  then
    if CS.Engine.Lib.AppEngine.GetAppBundleVersion().Server == 'pre' then
        GameUtils.Toast(localize("当前平台不支持充值，请前往移动平台充值"))
        return
    end
    if GameUtils.GetChannelId() == DMM_CHANNEL_ID and not isSkip then
        self:PayDmmMoney(parameters)
        return
    end
    local productId = checkString(parameters.productId)
    if self:IsCommonSDK() then
        ---@type UserComponent
        local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
        local openId = ""
        if userComponent then
            openId = tostring(userComponent.userInfo.openId)
        end
        ---@type PlayerComponent
        local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        GameUtils.Request(Interfaces.PayOrder, { productId = productId },
                function(request, response)
                    if checkNumber(response.errCode) == 0 then
                        local data = checkTable(response.data)

                        -- 日服充值限制
                        if checkInt(data.age) ~= 0 and checkInt(data.orderNo) == 0 then
                            GameUtils.ShowPayLimitTips(data.left, data.age)
                            self:CloseNetWorkDialog()
                            return
                        end

                        local payInfo = PayInfo()
                        payInfo.productId = checkString(parameters.channelProductId)
                        payInfo.openId = openId
                        payInfo.productDesc = checkString(parameters.productDesc)
                        payInfo.productName = checkString(parameters.productDesc)
                        -- amount 是以分为单位的 上传之前必须乘以100
                        payInfo.payAmount = checkString(checkInt(checkNumber(parameters.payAmount) * 100))
                        --payInfo.serverId = userComponent.userInfo.serverId
                        -- 这里面服务器id 和服务器名字直接写死  
                        local serverId, serverName = self:GetServerIdAndServerName()
                        payInfo.serverId = tostring(serverId)
                        payInfo.serverName = serverName or "Cat Funtasy"
                        payInfo.roleId = playerComponent.playerDojo.playerId
                        payInfo.roleName = playerComponent.playerDojo.playerName
                        payInfo.roleLevel = playerComponent.playerDojo.level
                        payInfo.vipLevel = "1"
                        payInfo.balance = tostring(playerComponent.playerDojo.diamond)
                        local orderNo = checkString(data.orderNo)
                        --table.insert(self.__orderNo, orderNo)
                        payInfo.gameTradeNo = orderNo
                        payInfo.additionalParams = table.serialize({
                            channelProductId = checkString(parameters.channelProductId),
                            productDesc = checkString(parameters.productDesc),
                            productId = checkString(parameters.productId),
                            payAmount = checkString(parameters.payAmount)
                        })
                        local AppEngine = CS.Engine.Lib.AppEngine
                        payInfo.for_review = tostring(checkInt(IS_REVIEW_INT))
                        -- 调起遮罩放在放在调起充值之后
                        --if kTool.UNITY_IOS() or self:IsXosllaSDK() then
                        xTry(function()
                            local dialog = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.UINetWorkPlaying)
                            if isNull(dialog) then
                                UIModule.OpenDialog({ id = Constants.UITypeIds.UINetWorkPlaying })
                            end
                        end)
                        --end
                        if GameUtils.IsWindow() then
                            if GameUtils.GetChannelId() == DMM_CHANNEL_ID then
                                ---支付相关的参数填入
                                Events.Broadcast(Constants.EventNames.WinSDK, { type = 999, responseData = data, reqData = parameters })
                            else
                                Events.Broadcast(Constants.EventNames.WinSDK, { type = 4, responseData = data, reqData = parameters })
                            end
                        else
                            SDKCenter.Pay(payInfo)
                        end
                    end
                end, function(exception)
                    self:CloseNetWorkDialog()
                    GameUtils.Toast(exception.Message)
                end)
    else
        GameUtils.Toast(localize("该平台不支持充值"))
    end
end

