---@deprecated 分享
---@param shareType Constants.ShareChannel @ 分享渠道
---@param imgPath string @ 分享路径
---@param title string @ 分享主题
---@param content string @ 分享内容
---@param groupName string @ 超话名
---@param groupSection string @ 超话板块
function SDKService:Share(shareType, imgPath, title, content, url, groupName, groupSection)
    --line ios 目前还可以分享图片 ,但是android 不可以了
    if shareType == Constants.ShareChannel.LINE and kTool.UNITY_ANDROID() then
        imgPath = ""
        content = string.url_encode(content)
    end
    local t = nil
    if self.IsCN and self:IsCN() then
        t = {
            type = shareType or Constants.ShareChannel.FB,
            imgPath = imgPath or "",
            title = title or "",
            content = content or "",
            url = url or "",
            groupName = groupName or "",
            groupSection = groupSection or "",
        }
    else
        t = {
            type = shareType or Constants.ShareChannel.FB,
            shares = {
                [1] = {
                    type = shareType or Constants.ShareChannel.FB,
                    imgPath = imgPath or "",
                    title = title or "",
                    content = content or "",
                    url = url or "",
                    groupName = groupName or "",
                    groupSection = groupSection or "",
                }
            }
        }
        if kTool.UNITY_IOS() then
            if shareType == Constants.ShareChannel.FB then
                if string.len(imgPath) > 0 then
                    shareType = 51
                else
                    shareType = 50
                end
            elseif shareType == Constants.ShareChannel.LINE then
                if imgPath and string.len(imgPath) > 0 then
                    shareType = 71
                elseif url and string.len(url) > 0 then
                    shareType = 72
                else
                    shareType = 70
                end
            elseif shareType == Constants.ShareChannel.INS_FEED_SHARE or shareType == Constants.ShareChannel.INS_STORY_SHARE then
                shareType = Constants.ShareChannel.INS_FEED_SHARE
            end
            t = {
                type = shareType,
                imgPath = imgPath or "",
                title = title or "",
                content = content or "",
                url = url or "",
                groupName = groupName or "",
                groupSection = groupSection or "",
            }
        end
    end

    -- 分享B 站也要支持
    if self:IsCommonSDK() then
        --打开横屏 ios 要关闭音乐
        if kTool.UNITY_IOS() and checkInt(shareType) == Constants.ShareChannel.FTCommunity then
            ---@type CriWareUtils
            local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
            CriWareUtils.SetVolume(Constants.CriWareCategory.BGM, 0)
        end
        if kTool.IsMobile() then
            SDKCenter.InvokePlugin(ProxyPluginName, "share", table.serialize(t))
        end

    end
end

