function SDKService:GetServerIdAndServerName()
    local HttpModule = CS.Engine.Http.HttpModule
    local serverId = HttpModule.RequestBodyMeta.serverId
    ---@type UserComponent
    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
    ---@ serverDojo
    local serverDojo = userComponent:GetServerListById(serverId)
    if isNull(serverDojo) then
        if userComponent.userInfo.servers and #userComponent.userInfo.servers > 0 then
            serverDojo = userComponent.userInfo.servers[1]
        end
    end
    --TODO serverDojo可能为空
    local serverId = serverDojo and serverDojo.serverId or 1
    local serverName = serverDojo and serverDojo.serverName or "Cat Funtasy"
    return serverId, serverName
end

