function SDKService:UploadRole(roleId, roleName)
    --if kTool.IsMobile() then
    ---@type ECSWorldMgr
    local worldMgr = ECSWorldMgr:GetInstance()
    ---@type ECSWorld
    local world = worldMgr:GetWorld(Constants.GameWorld)
    ---@type ECSEntity
    local entity = world:GetEntity(Constants.PlayerEntityId)
    ---@type UserComponent
    local userComp = entity:GetOrAddComp(ECSComponentType.Constants.UserComponent)
    local openId = ""
    if userComp.userInfo then
        openId = userComp.userInfo.openId
    end
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local playerDojo = playerComponent.playerDojo
    local serverId, serverName = self:GetServerIdAndServerName()
    local roleData = {
        roleId = tostring(playerDojo.playerId),
        roleName = tostring(playerDojo.playerName),
        roleLevel = tostring(playerDojo.level),
        RechargePts = tostring(userComp:GetSumPayCumulative()),
        account = openId,
        serverName = serverName,
        serverId = tostring(serverId) ,
        pay_point = tostring(userComp:GetSumPayCumulative()) ,
        gameJson = table.serialize({
        role_power = "0"
        }) 
    }
    if GameUtils.IsWindow() then
        xTry(function()
            local af_device_id = CS.UnityEngine.PlayerPrefs.GetString("af_device_id", "")
            if not string.isEmpty(af_device_id) then
                local WWWEx = CS.Engine.Lib.Updater.WWWEx
                local wwwEx = WWWEx.MakeWWWEx("pay/appsFlyer", { appsFlyerId = af_device_id }, GetApiSalt(), 3, 10)
                local cs_coroutine = require('XLua.cs_coroutine')
                cs_coroutine.start(function()
                    cs_coroutine.yield_return(wwwEx:LoadAsync(nil, nil))
                end)
            end
        end)
        Events.Broadcast(Constants.EventNames.WinSDK, { type = 9, role = roleData })
    elseif kTool.IsMobile() then
        -- 这里智明需要先上传角色信息
        local roleData2 = clone(roleData)
        roleData2.customData = table.serialize(
                {
                    RechargePts = userComp:GetSumPayCumulative(),
                    AccountID = tostring(userComp.userInfo.openId)
                }
        )
        self:updateElexUserInfo(roleData2)
        SDKCenter.InvokePlugin(ProxyPluginName, 'uploadRole', table.serialize(roleData))
        self:AceSDKCall("AceDataSend2")
    end

    -- end
end

