---IsCommonSDK
---是否可以走通用sdk 逻辑
function SDKService:IsCommonSDK()
    return self:IsOfficialSDK() or self:IsBilibiliSDK() or self:IsForeignSDK() or self:IsChannelSdk()
end

---IsForeign
---是否可以海外渠道sdk 逻辑
function SDKService:IsForeignSDK()
    local channelId = GameUtils.GetChannelId()
    return channelId >= 5000 and channelId < 6000 or self:IsOneStore()
end
---IsChannalSdk
---是否可以海外非官方渠道渠道sdk 逻辑
function SDKService:IsChannelSdk()
    local channelId = GameUtils.GetChannelId()
    return channelId > 6000
end

function SDKService:IsWindowSdk()
    return GameUtils.IsWindow()
end

function SDKService:IsXosllaSDK()
    if not self:IsCommonSDK() then
        return false
    end
    if kTool.UNITY_IOS() then
        return false
    end
    if GameUtils.IsWindow() then
        return false
    end
    local property = typeof(CS.Engine.Lib.AndroidPlugin):GetProperty("IsGoogle")
    if isNull(property) then
        return false
    end
    if self:IsChannelSdk() then
        return false
    end
    return (not CS.Engine.Lib.AndroidPlugin.IsGoogle)
end

