function SDKService:updateElexUserInfo(content)
    if self:IsZm() and kTool.IsMobile() then
        if content.roleId then
            content.userId = tostring(content.roleId)
            content.userName = tostring(content.roleName)
        else
            content.userId = ""
            content.userName = ""
        end
        content.lang = "en-US"
        ---@type UserComponent
        local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
        content.customData = table.deserialize({
            AccountlD = userComponent.userInfo.openId
        })
        SDKCenter.InvokePlugin(ProxyPluginName, "updateElexUserInfo", table.serialize(content))
    end
end

