function SDKService:GetThirdSDK(key)
    if isNull(self.thirdSDK[key]) then
        self.thirdSDK[key] = import(string.format("Game.Sdk.%s", key)).New(self)
    end
    return self.thirdSDK[key]
end

function SDKService:AceSDKCall(method, ...)
    local AceUtils = self:GetThirdSDK("AceUtils")
    AceUtils[method](AceUtils, ...)
end
function SDKService:PayUtilsCall(method, ...)
    local PayUtils = self:GetThirdSDK("PayUtils")
    return PayUtils[method](PayUtils, ...)
end

---GetUserComponent
---@return UserComponent
function SDKService:GetUserComponent()
    ---@type ECSWorldMgr
    local worldMgr = ECSWorldMgr:GetInstance()
    ---@type ECSWorld
    local world = worldMgr:GetWorld(Constants.GameWorld)
    ---@type ECSEntity
    local entity = world:GetEntity(Constants.PlayerEntityId)
    ---@type UserComponent
    local userComp = entity:GetOrAddComp(ECSComponentType.Constants.UserComponent)
    return userComp
end

---DMMExecute 执行dmm的逻辑类型
---@param executeType number 类型1为登录 2为支付调用的逻辑
---@param cb function 回调的逻辑
---@param data table 支付的调用数据 {itemId = xx, name=xxx, price = xxx, quantity = xxx, callbackUrl = xxx, finishUrl = xxx}
function SDKService:DMMExecute(executeType, cb, data)
    if type(typeof(CS.DMM.Games.Client.Sdk.NetGameApiSdk)) == 'userdata' then
        local DMMClientType = typeof(CS.DMM.Games.Client.Sdk.NetGameApiSdk)
        local Kind = CS.DMM.Games.Client.Sdk.NetGameApiSdk.Kind
        local NetGameApiSdkArgsModel = CS.DMM.Games.Client.Sdk.NetGameApiSdkArgsModel
        local NetGameApiResultType = typeof(CS.DMM.Games.Client.Sdk.NetGameApiResult)
        local args = NetGameApiSdkArgsModel.Load()
        ---@type Game.Native.Game
        local GameEntry = CS.Game.Native.Game
        ---@type DMM.Games.Client.Sdk.NetGameApiSdk
        local netGameApiSdk = kTool.GetOrAddComponent(GameEntry.Instance.gameObject, DMMClientType)
        local function OnSuccessCallback(kind, sender, result)
            debug_file("===>>" .. tostring(kind))
            debug_file(result:ToJson())
            --{"result_code":0,"access_token":"","onetime_token":"78f21c3396e11be11eee652eac8c98fe","can_use_point":0,"can_use_chip":0,"nickname":"","install_status":false,"payment_id":"","accept_time":1727167007}
            local ret = table.deserialize(result:ToJson())
            ---@type UserComponent
            local userComp = self:GetUserComponent()
            if kind == Kind.CheckLogin then
                ---设置相关的accessToken的逻辑
                if userComp then
                    ---@type UserDojo
                    local userDojo = userComp.userInfo
                    if not string.isEmpty(ret.onetime_token) then
                        userDojo.oneTimeAccessToken = checkString(ret.onetime_token)
                    end
                end
                if cb then
                    cb(kind)
                end
            elseif kind == Kind.GetProfile then
                if userComp then
                    ---@type UserDojo
                    local userDojo = userComp.userInfo
                    userDojo.nickName = tostring(ret.nickname)
                end
            elseif kind == Kind.GetPoint then
                --debug_file(result:ToJson())
                if userComp then
                    --debug_file(result:ToJson())
                    ---@type UserDojo
                    local userDojo = userComp.userInfo
                    --debug_file(ret.can_use_point)
                    userDojo.canUsePoint = checkNumber(ret.can_use_point)
                    --debug_file(userDojo.canUsePoint)
                end
            elseif kind == Kind.GetChip then
                if userComp then
                    ---@type UserDojo
                    local userDojo = userComp.userInfo
                    userDojo.canUseChip = checkNumber(ret.can_use_chip)
                end
            elseif kind == Kind.Payment then
                if cb then
                    cb(kind, ret)
                end
            end
        end

        local function OnFailedCallback(kind, sender, error)
            debug_file("===>>failed" .. tostring(kind))
            GameUtils.Toast(tostring(kind) .. " error: " .. tostring(error))
        end

        local function Initialize(viewId, oneTimeToken, accessToken)
            if not netGameApiSdk.IsInitialized then
                debug_file("===>>xxx")
                netGameApiSdk:Initialize(accessToken, viewId, oneTimeToken, Config.DEBUG)
            end
            debug_file("===>>xxx")
            if netGameApiSdk.IsInitialized then
                if checkInt(executeType) == 1 then
                    ---登录后的信息记录
                    ---再去检查登录
                    netGameApiSdk:CheckLogin(function(k, s, r)
                        OnSuccessCallback(k, s, r)
                        netGameApiSdk:GetPoint(OnSuccessCallback, OnFailedCallback)
                        --netGameApiSdk:GetProfile(OnSuccessCallback, OnFailedCallback)
                        --netGameApiSdk:GetChip(OnSuccessCallback, OnFailedCallback)
                    end, OnFailedCallback)
                    --netGameApiSdk:UpdateToken(function(kind, sender, result)
                    --    if kind == Kind.UpdateToken then
                    --        local json = result:ToJson()
                    --        debug_file("===>> " .. json)
                    --        ---@type UserComponent
                    --        local userComp = self:GetUserComponent()
                    --        if userComp then
                    --            ---@type UserDojo
                    --            local userDojo = userComp.userInfo
                    --            if not string.isEmpty(json.onetime_token) then
                    --                userDojo.oneTimeAccessToken = checkString(json.onetime_token)
                    --            end
                    --            if not string.isEmpty(json.access_token) then
                    --                userDojo.dmmAccessToken = checkString(json.access_token)
                    --            end
                    --        end
                    --
                    --    end
                    --end, OnFailedCallback)
                elseif checkInt(executeType) == 2 then
                    netGameApiSdk:Payment(data.itemId,
                            data.name,
                            data.price,
                            data.quantity,
                            data.callbackUrl,
                            data.finishUrl,
                            OnSuccessCallback,
                            OnFailedCallback)
                elseif checkInt(executeType) == 3 then
                    ---获取一次点数据
                    netGameApiSdk:GetPoint(function(k, s, r)
                        OnSuccessCallback(k, s, r)
                        if cb then
                            cb(k)
                        end
                    end , OnFailedCallback)
                    --netGameApiSdk:GetProfile(OnSuccessCallback, OnFailedCallback)
                    --netGameApiSdk:GetChip(OnSuccessCallback, OnFailedCallback)
                end
            end
        end
        if isNull(args) then
            ---如果为空的话
            local argsString = CS.System.Environment.GetCommandLineArgs()
            ---@type UserComponent
            local userComp = self:GetUserComponent()
            if userComp then
                ---@type UserDojo
                local userDojo = userComp.userInfo
                for k, v in array_pairs(argsString) do
                    if string.contains(v, "/viewer_id") then
                        local vv = string.gsub(v, "/viewer_id=", "")
                        userDojo.viewId = string.trim(vv)
                    elseif string.contains(v, "/onetime_token") then
                        local vv = string.gsub(v, "/onetime_token=", "")
                        userDojo.oneTimeAccessToken = string.trim(vv)
                    elseif string.contains(v, "/access_token") then
                        local vv = string.gsub(v, "/access_token=", "")
                        userDojo.dmmAccessToken = string.trim(vv)
                    end
                end
                debug_file("===>>参数未获取过" .. userDojo.viewId .. userDojo.oneTimeAccessToken .. userDojo.dmmAccessToken)
                Initialize(userDojo.viewId, userDojo.oneTimeAccessToken, userDojo.dmmAccessToken)
            end
        else
            local viewId = args.ViewerId
            local oneTimeToken = args.OnetimeToken
            local accessToken = args.AccessToken
            ---@type UserComponent
            local userComp = self:GetUserComponent()
            if userComp then
                ---@type UserDojo
                local userDojo = userComp.userInfo
                userDojo.viewId = viewId
                userDojo.dmmAccessToken = accessToken
                userDojo.oneTimeAccessToken = oneTimeToken
                debug_file("===>>参数中获到过" .. userDojo.viewId .." " ..  userDojo.oneTimeAccessToken .." " ..  userDojo.dmmAccessToken)
                Initialize(viewId, oneTimeToken, accessToken)
            end

        end
    end
end

return SDKService

